config.fmfTickSource:
onTick(dt) {
      GameState.fmfTimeLeft -= dt;
      if (GameState.fmfTimeLeft <= 0) {
        GameState.fmfTimeLeft = 0;
        triggerGameOver("Time's Up!", 'Five Minute Feast Complete!', 'timer', true);
      }
    }

